INSERT INTO `decision_group` VALUES
(1,1,'consultation','majority_judgment','Comment modifieriez vous la raison d\'être de l\'instant Z','Libérer le potentiel des organisations\r\n\r\nNous sommes une équipe d\'experts soutenant la transformation culturelle des organisations vers plus de confiance dans le potentiel individuel et collectif de ses membres et plus de conscience de leur contribution au monde.\r\n\r\nEn lien avec un réseau de partenaires engagés dans la transformation sociétale, nous explorons, pratiquons et transmettons des outils et une philosophie soutenant l\'être et le faire ensemble, développant le leadership individuel, favorisant l\'intelligence collective et s\'assurant de relations humaines libres et authentiques.\r\n\r\nNous souhaitons ainsi permettre à des organisations qui oeuvrent à un avenir enviable d\'appliquer des méthodes de management assurant cohérence, engagement et efficacité et soutenant leurs membres dans le développement de leur pouvoir d\'agir et leur sens des responsabilités.','{\"majority_judgment\":{\"is_anonymous\":0,\"allow_consultation_proposals\":1,\"mention_customization_enabled\":0,\"scale_size\":7,\"mention_options\":[{\"label\":\"A rejeter\",\"active\":1},{\"label\":\"Insuffisant\",\"active\":1},{\"label\":\"Passable\",\"active\":1},{\"label\":\"Sans avis\",\"active\":1},{\"label\":\"Assez bien\",\"active\":1},{\"label\":\"Très bien\",\"active\":1},{\"label\":\"Excellent\",\"active\":1}],\"vote_weighting\":{\"enabled\":0,\"question\":\"\",\"options\":[{\"weight\":\"1\",\"label\":\"Souhaitable\"}]},\"proposal_count\":3,\"created_from_module\":\"majority_judgment\",\"allow_proposal_discussions\":1,\"allow_anonymous_votes\":0,\"show_live_results\":0},\"decision_public_access\":{\"allow_self_registration\":0},\"decision_invitation_mail\":{\"last_message\":\"Bonjour,\\r\\n\\r\\nVous etes invite a participer a la prise de decision \\\"Relecture de la raison d\'être\\\" dans OpenMyOrganization.\\r\\nContexte: Cercle Ancrage.\\r\\nDebut: 31.07.2026 14:40.\\r\\nFin: 16.08.2026 14:40.\\r\\n\\r\\nVous pouvez consulter les details du scrutin en ouvrant le lien ci-dessous.\\r\\n\\r\\nA bientot,\\r\\nOpenMyOrganization\",\"last_sent_at\":\"2026-07-31T14:43:48+02:00\",\"last_sent_by\":1,\"last_recipient_count\":2,\"last_failed_count\":0,\"last_subject\":\"Acces a la prise de decision : Relecture de la raison d\'être\",\"last_scope\":\"pending\"}}',1,1,'2026-07-31 12:43:22','2026-07-31 12:43:22'),
