(22,'omo_parameters_holon_templates','en','4e48d5b40f48a478abf8cb59509f11c4747309fadaa196dde0bdcd243f99503e','{\"parameters.holon_templates.action.add_property\":{\"context\":\"Button label used to add a property in the holon template editor.\",\"text\":\"Ajouter une propriété\"},\"parameters.holon_templates.action.close\":{\"context\":\"Close button label used in compact mode for the holon template editor.\",\"text\":\"Fermer\"},\"parameters.holon_templates.action.delete_model\":{\"context\":\"Destructive action used to delete the selected holon template.\",\"text\":\"Effacer\"},\"parameters.holon_templates.action.new_model\":{\"context\":\"Primary button label used to create a new root holon template.\",\"text\":\"Nouveau modèle\"},\"parameters.holon_templates.action.new_submodel\":{\"context\":\"Secondary button label used to create a child holon template.\",\"text\":\"Sous-modèle\"},\"parameters.holon_templates.action.resize_columns\":{\"context\":\"Accessible label for the draggable separator between the template tree and editor columns.\",\"text\":\"Ajuster la largeur des colonnes\"},\"parameters.holon_templates.action.save_model\":{\"context\":\"Submit button label used in template mode for the holon template editor.\",\"text\":\"Enregistrer\"},\"parameters.holon_templates.action.save_organization\":{\"context\":\"Submit button label used in organization definition mode for the holon template editor.\",\"text\":\"Enregistrer l\'organisation\"},\"parameters.holon_templates.badge.active_inheritance\":{\"context\":\"Badge shown when a template inherits from another one in the holon template editor.\",\"text\":\"Héritage actif\"},\"parameters.holon_templates.confirm.delete_model\":{\"context\":\"Confirmation shown before deleting a holon template and its child templates.\",\"text\":\"Effacer le modèle {templateName} ?\\\\n\\\\nSes sous-modèles seront également supprimés. Cette action est définitive.\"},\"parameters.holon_templates.confirm.inheritance_change\":{\"