(23,'omo_decision_public','en','5f8f9bdb60a71cd1b1f00dcee4b307bcd44e57056c69e1c528e78540aefed4e4','{\"decisions.public.access.code\":{\"context\":\"Access code field label on the public access form.\",\"text\":\"Code reçu par e-mail\"},\"decisions.public.access.code_placeholder\":{\"context\":\"Access code field placeholder on the public access form.\",\"text\":\"123456\"},\"decisions.public.access.code_sent\":{\"context\":\"Public access success after sending an access code.\",\"text\":\"Un code personnel et un lien direct viennent d’être envoyés à {email}.\"},\"decisions.public.access.code_valid\":{\"context\":\"Public access success after code verification.\",\"text\":\"Code valide. Redirection en cours…\"},\"decisions.public.access.code_verification_failed\":{\"context\":\"Fallback public access error during code verification.\",\"text\":\"Impossible de vérifier ce code pour le moment.\"},\"decisions.public.access.consume_failed\":{\"context\":\"Public access error when code consumption fails.\",\"text\":\"Le code est correct, mais l’accès n’a pas pu être finalisé. Réessayez dans un instant.\"},\"decisions.public.access.create_failed\":{\"context\":\"Public access error when participation creation fails.\",\"text\":\"Impossible de créer cette participation pour le moment.\"},\"decisions.public.access.email\":{\"context\":\"Email field label on the public access form.\",\"text\":\"Adresse e-mail\"},\"decisions.public.access.email_placeholder\":{\"context\":\"Email field placeholder on the public access form.\",\"text\":\"nom@exemple.org\"},\"decisions.public.access.empty_code\":{\"context\":\"Public access error for an empty access code.\",\"text\":\"Merci de saisir le code reçu par e-mail.\"},\"decisions.public.access.enter\":{\"context\":\"Button validating the public access code.\",\"text\":\"Accéder au scrutin\"},\"decisions.public.access.expired_code\":{\"context\":\"Public access error for an expired code.\",\"text\":\"Ce code a expiré. Demandez-en un nouveau depuis cette page.\"},\"decisions.public.access.finalize_failed\":{\"context\":\"Public access error when the personal link cannot be finalized.\",\"text\":\"Le lien personnel n’a pas pu être finalisé. Réessayez dans un instant.\"},\"decisions.public.access.invalid_code\":{\"context\":\"Public access error for an invalid code.\",\"text\":\"Le code saisi est incorrect.\"},\"decisions.public.access.invalid_decision\":{\"context\":\"Public access error when the decision cannot be found.\",\"text\":\"Cette prise de décision est introuvable.\"},\"decisions.public.access.invalid_email\":{\"context\":\"Public access error for an invalid email address.\",\"text\":\"Merci de saisir une adresse e-mail valide.\"},\"decisions.public.access.invited_description\":{\"context\":\"Description of invited public access registration.\",\"text\":\"Saisissez l’adresse e-mail autorisée pour ce scrutin afin de recevoir un code personnel ainsi qu’un lien direct de participation.\"},\"decisions.public.access.missing_code\":{\"context\":\"Public access error when no code exists.\",\"text\":\"Aucun code valide n’a été trouvé pour cette adresse. Demandez-en un nouveau.\"},\"decisions.public.access.not_allowed_invited\":{\"context\":\"Public access error when the email is not invited.\",\"text\":\"Cette adresse e-mail ne fait pas partie des personnes autorisées à participer à ce scrutin.\"},\"decisions.public.access.not_allowed_open\":{\"context\":\"Public access error when open registration does not accept the email.\",\"text\":\"Cette adresse e-mail ne peut pas être utilisée pour ce scrutin pour le moment.\"},\"decisions.public.access.open_description\":{\"context\":\"Description of open public access registration.\",\"text\":\"Saisissez votre adresse e-mail pour recevoir un code personnel ainsi qu’un lien direct personnel. Si cette adresse n’est pas encore associée à ce scrutin, une participation sera créée automatiquement.\"},\"decisions.public.access.participant_unavailable\":{\"context\":\"Public access error for an unavailable participant.\",\"text\":\"Cette adresse e-mail est déjà liée à un participant qui ne peut plus utiliser ce scrutin.\"},\"decisions.public.access.resend\":{\"context\":\"Button resending a public access code.\",\"text\":\"Renvoyer le code\"},\"decisions.public.access.send\":{\"context\":\"Button requesting a public access code.\",\"text\":\"Envoyer mon accès\"},\"decisions.public.access.sync_failed\":{\"context\":\"Public access error when participants cannot be synchronized.\",\"text\":\"Impossible de vérifier les participants autorisés pour le moment.\"},\"decisions.public.access.title\":{\"context\":\"Title on the public access request form.\",\"text\":\"Recevoir mon accès personnel\"},\"decisions.public.access.title_eyebrow\":{\"context\":\"Eyebrow title on the public access request form.\",\"text\":\"Accès public\"},\"decisions.public.banner\":{\"context\":\"Public decision page banner.\",\"text\":\"Scrutin public organisé pour {organization}\"},\"decisions.public.banner_personal_access\":{\"context\":\"Personal access suffix in the public decision page banner.\",\"text\":\" · accès personnel de {participant}\"},\"decisions.public.banner_prefix\":{\"context\":\"Prefix in the public decision page banner before the organization name.\",\"text\":\"Scrutin public organisé pour\"},\"decisions.public.block\":{\"context\":\"Public label for a decision block.\",\"text\":\"Bloc {index}\"},\"decisions.public.block_unavailable\":{\"context\":\"Fallback shown when a public decision block has no renderer.\",\"text\":\"Ce bloc ne dispose pas encore d’une interface disponible.\"},\"decisions.public.context.contact_organizer\":{\"context\":\"Public contact label for the organizer.\",\"text\":\"Contacter l’organisateur :\"},\"decisions.public.context.invited\":{\"context\":\"Public context card title for invited participants.\",\"text\":\"Invités\"},\"decisions.public.context.method\":{\"context\":\"Public context card title for one method.\",\"text\":\"Méthode\"},\"decisions.public.context.methods\":{\"context\":\"Public context card title for several methods.\",\"text\":\"Méthodes\"},\"decisions.public.context.options\":{\"context\":\"Public context card title for decision options.\",\"text\":\"Options\"},\"decisions.public.context.organizer\":{\"context\":\"Public context card title for the organizer.\",\"text\":\"Organisateur\"},\"decisions.public.default_organization\":{\"context\":\"Fallback organization name on the public decision page.\",\"text\":\"Organisation\"},\"decisions.public.default_title\":{\"context\":\"Fallback decision title on the public page.\",\"text\":\"Prise de décision\"},\"decisions.public.help.webmaster\":{\"context\":\"Server administrator email link shown below the public decision help items.\",\"text\":\"Webmaster : {email}\"},\"decisions.public.js.access_process_failed\":{\"context\":\"JavaScript fallback when processing a public access request fails.\",\"text\":\"Impossible de traiter cette demande pour le moment.\"},\"decisions.public.js.code_sent\":{\"context\":\"JavaScript fallback after sending a public access code.\",\"text\":\"Code envoyé.\"},\"decisions.public.js.invalid_response\":{\"context\":\"JavaScript fallback when the proposal response is invalid.\",\"text\":\"Réponse invalide du serveur.\"},\"decisions.public.js.proposal_add_failed\":{\"context\":\"JavaScript fallback when adding a consultation proposal fails.\",\"text\":\"Impossible d’ajouter la proposition pour le moment.\"},\"decisions.public.js.proposal_placeholder\":{\"context\":\"JavaScript prefix for a consultation proposal input placeholder.\",\"text\":\"Proposition\"},\"decisions.public.js.remove_proposal\":{\"context\":\"JavaScript label for removing a consultation proposal input.\",\"text\":\"Supprimer\"},\"decisions.public.method.consent\":{\"context\":\"Public label for the consent method.\",\"text\":\"Consentement\"},\"decisions.public.method.majority_judgment\":{\"context\":\"Public label for the majority judgment method.\",\"text\":\"Jugement majoritaire\"},\"decisions.public.method.simple_vote\":{\"context\":\"Public label for the simple vote method.\",\"text\":\"Vote simple\"},\"decisions.public.method.unknown\":{\"context\":\"Fallback public label for an unknown decision method.\",\"text\":\"Mode de décision\"},\"decisions.public.navigation.aria\":{\"context\":\"Public decision page mobile navigation label.\",\"text\":\"Navigation du scrutin\"},\"decisions.public.navigation.decision\":{\"context\":\"Public decision page mobile decision tab.\",\"text\":\"Scrutin\"},\"decisions.public.navigation.help\":{\"context\":\"Public decision page help label.\",\"text\":\"Aide\"},\"decisions.public.navigation.info\":{\"context\":\"Public decision page mobile information tab.\",\"text\":\"Infos\"},\"decisions.public.options.anonymous\":{\"context\":\"Public option indicating that the decision is anonymous.\",\"text\":\"Ce scrutin est anonyme.\"},\"decisions.public.options.discussions_all\":{\"context\":\"Public option when discussions are allowed in every block.\",\"text\":\"Vous pouvez discuter les propositions pendant la consultation\"},\"decisions.public.options.discussions_anonymous\":{\"context\":\"Suffix when discussion anonymity is mandatory.\",\"text\":\" de façon anonyme.\"},\"decisions.public.options.discussions_optional_anonymity\":{\"context\":\"Suffix when participants may discuss anonymously.\",\"text\":\", anonymement si vous le souhaitez.\"},\"decisions.public.options.discussions_some\":{\"context\":\"Public option when discussions are allowed in some blocks.\",\"text\":\"Vous pouvez discuter les propositions pendant la consultation pour certains blocs\"},\"decisions.public.options.mixed_anonymity\":{\"context\":\"Public option indicating mixed anonymity settings.\",\"text\":\"Le caractère anonyme peut varier selon les blocs.\"},\"decisions.public.options.not_anonymous\":{\"context\":\"Public option indicating that the decision is not anonymous.\",\"text\":\"Ce scrutin n’est pas anonyme.\"},\"decisions.public.options.proposals_all\":{\"context\":\"Public option when proposals are allowed in every block.\",\"text\":\"Vous pouvez faire des propositions durant la consultation.\"},\"decisions.public.options.proposals_some\":{\"context\":\"Public option when proposals are allowed in some blocks.\",\"text\":\"Vous pouvez faire des propositions durant la consultation pour certains blocs.\"},\"decisions.public.options.responses_editable\":{\"context\":\"Public option indicating that responses can still be changed.\",\"text\":\"Vos réponses sont modifiables.\"},\"decisions.public.options.responses_locked\":{\"context\":\"Public option indicating that responses can no longer be changed.\",\"text\":\"Vos réponses ne sont plus modifiables.\"},\"decisions.public.options.results_hidden\":{\"context\":\"Public option indicating that results are hidden.\",\"text\":\"Les résultats ne sont pas visibles avant la fin du vote.\"},\"decisions.public.options.results_visible\":{\"context\":\"Public option indicating that results are visible.\",\"text\":\"Les résultats sont visibles.\"},\"decisions.public.status.can_participate\":{\"context\":\"Public status when participation is available.\",\"text\":\"Vous pouvez participer à ce scrutin depuis cette page publique.\"},\"decisions.public.status.request_invited\":{\"context\":\"Public access prompt when only invited emails may request access.\",\"text\":\"Entrez votre adresse e-mail autorisée pour recevoir un code personnel de participation.\"},\"decisions.public.status.request_open\":{\"context\":\"Public access prompt when self-registration is open.\",\"text\":\"Entrez votre adresse e-mail pour recevoir un code personnel de participation.\"},\"decisions.public.status.unavailable\":{\"context\":\"Public status when the decision cannot be accessed.\",\"text\":\"Ce lien ne permet pas d’accéder à cette prise de décision.\"},\"decisions.public.timeline.consultation_end\":{\"context\":\"Consultation end milestone label.\",\"text\":\"Fin de la consultation\"},\"decisions.public.timeline.consultation_open\":{\"context\":\"Timeline summary while consultation is open without an end date.\",\"text\":\"En consultation\"},\"decisions.public.timeline.consultation_start\":{\"context\":\"Consultation start milestone label.\",\"text\":\"Début de la consultation\"},\"decisions.public.timeline.consultation_until\":{\"context\":\"Timeline summary while consultation is open with an end date.\",\"text\":\"En consultation jusqu’au {date}\"},\"decisions.public.timeline.evaluation_end\":{\"context\":\"Evaluation end milestone label.\",\"text\":\"Fin du vote\"},\"decisions.public.timeline.evaluation_start\":{\"context\":\"Evaluation start milestone label.\",\"text\":\"Début du vote\"},\"decisions.public.timeline.finished\":{\"context\":\"Timeline summary after the decision is finished.\",\"text\":\"Terminé\"},\"decisions.public.timeline.hint\":{\"context\":\"Public timeline accordion hint.\",\"text\":\"Afficher la représentation graphique\"},\"decisions.public.timeline.now\":{\"context\":\"Current moment label on the public decision timeline.\",\"text\":\"Maintenant\"},\"decisions.public.timeline.results\":{\"context\":\"Results milestone label.\",\"text\":\"Résultats\"},\"decisions.public.timeline.segment_consultation\":{\"context\":\"Timeline segment label for consultation.\",\"text\":\"Consultation\"},\"decisions.public.timeline.segment_results\":{\"context\":\"Timeline segment label for results.\",\"text\":\"Résultats\"},\"decisions.public.timeline.segment_vote\":{\"context\":\"Timeline segment label for evaluation.\",\"text\":\"Vote\"},\"decisions.public.timeline.title\":{\"context\":\"Public timeline accordion title.\",\"text\":\"Étapes du scrutin\"},\"decisions.public.timeline.vote_open\":{\"context\":\"Timeline summary while voting is open without an end date.\",\"text\":\"Vote ouvert\"},\"decisions.public.timeline.vote_until\":{\"context\":\"Timeline summary while voting is open with an end date.\",\"text\":\"Vote ouvert jusqu’au {date}\"},\"decisions.public.timeline.waiting_consultation\":{\"context\":\"Timeline summary before consultation starts.\",\"text\":\"En attente du début de la consultation le {date}\"},\"decisions.public.timeline.waiting_vote\":{\"context\":\"Timeline summary before evaluation starts.\",\"text\":\"En attente du début du vote le {date}\"},\"decisions.public.type.consultation\":{\"context\":\"Public label for a consultation process.\",\"text\":\"consultation\"},\"decisions.public.type.decision\":{\"context\":\"Public label for a decision process.\",\"text\":\"décision\"}}','completed',1,NULL,'2026-08-01 09:08:55','2026-08-01 09:09:08','2026-08-01 09:08:56','2026-08-01 09:09:08'),
(24,'common_omo_public_pages','en','81f93460f052ecc06a3824190f355d4cbe7cc6a9e5a0873ab84c60589164cabf','{\"common.public_help.omo.description\":{\"context\":\"Short description of the public help entry explaining OpenMyOrganization.\",\"text\":\"Présentation rapide du logiciel\"},\"common.public_help.omo.paragraph_1\":{\"context\":\"First paragraph explaining the purpose and organizational structure of OpenMyOrganization.\",\"text\":\"OpenMyOrganization (OMO) est un logiciel collaboratif conçu pour aider une organisation à rendre sa structure, ses responsabilités et son fonctionnement plus clairs. Il permet de représenter les organisations, groupes, cercles, rôles et responsabilités, puis de centraliser les informations utiles au travail collectif.\"},\"common.public_help.omo.paragraph_2\":{\"context\":\"Second paragraph listing the main OpenMyOrganization applications and access model.\",\"text\":\"Selon les applications activées, OMO accompagne les prises de décision, les projets, les documents et procès-verbaux, le calendrier, les indicateurs, les checklists ainsi que les règles et autorités. Les droits d’accès dépendent du contexte et des responsabilités de chacun.\"},\"common.public_help.omo.paragraph_3\":{\"context\":\"Third paragraph presenting the practical collaborative value of OpenMyOrganization.\",\"text\":\"En rassemblant ces éléments dans leur contexte, OMO facilite la coopération au quotidien : les rôles et les responsabilités de chacun sont plus clairs, les décisions peuvent être préparées et suivies collectivement, et les règles, processus et projets restent documentés et accessibles.\"},\"common.public_help.omo.title\":{\"context\":\"Title of the public help entry explaining OpenMyOrganization.\",\"text\":\"Qu’est-ce qu’OpenMyOrganization ?\"},\"common.public_help.organization_fallback\":{\"context\":\"Fallback organization reference used in public help content when no organization name is available.\",\"text\":\"l’organisation concernée\"},\"common.public_help.page.decision_description\":{\"context\":\"Short description of the public decision page help entry.\",\"text\":\"Comprendre ce scrutin public\"},\"common.public_help.page.decision_paragraph_1\":{\"context\":\"First paragraph explaining the purpose of the public decision page.\",\"text\":\"Cette page est la porte d’accès publique à une prise de décision organisée par {organization}. Elle présente le contexte, les questions, la méthode choisie, les étapes et les règles utiles pour comprendre comment la consultation et le scrutin vont se dérouler.\"},\"common.public_help.page.decision_paragraph_2\":{\"context\":\"Second paragraph explaining available actions on the public decision page.\",\"text\":\"Selon les paramètres du scrutin et votre accès, vous pouvez consulter les informations, demander un accès personnel par e-mail, participer à la consultation ou au vote, et consulter les résultats lorsque leur publication est autorisée.\"},\"common.public_help.page.decision_paragraph_3\":{\"context\":\"Third paragraph explaining public proposals and proposal discussions.\",\"text\":\"Lorsque les propositions sont autorisées, vous pouvez aussi en ajouter pendant la consultation. Si les discussions sont activées, les participants disposant d’un compte peuvent échanger sur chaque proposition et, selon les paramètres, choisir de publier leur message anonymement.\"},\"common.public_help.page.decision_paragraph_4\":{\"context\":\"Fourth paragraph explaining how the information panel helps participants follow the public decision process.\",\"text\":\"Le panneau d’informations sert de repère pendant tout le processus : il rappelle qui organise le scrutin, pour qui il est ouvert, quelles sont les étapes prévues et quelles options de participation sont disponibles.\"},\"common.public_help.page.generic_description\":{\"context\":\"Short description of the generic public page help entry.\",\"text\":\"Comprendre cette page publique\"},\"common.public_help.page.generic_paragraph\":{\"context\":\"Explanation of a generic public OpenMyOrganization page.\",\"text\":\"Cette page publique présente une partie du contenu partagé par {organization}. Elle ne donne pas accès aux espaces internes qui ne font pas partie du lien public.\"},\"common.public_help.page.share_description\":{\"context\":\"Short description of the public structure page help entry.\",\"text\":\"Comprendre cette structure partagée\"},\"common.public_help.page.share_paragraph_1\":{\"context\":\"First paragraph explaining the public shared structure page.\",\"text\":\"Cette page sert à parcourir une structure organisationnelle partagée publiquement par {organization}. Vous pouvez y explorer les cercles, les rôles et les relations visibles dans le périmètre partagé.\"},\"common.public_help.page.share_paragraph_2\":{\"context\":\"Second paragraph explaining the limits of the public shared structure page.\",\"text\":\"Elle ne permet pas d’accéder aux espaces internes ni aux informations qui ne font pas partie du lien public.\"},\"common.public_help.page.title\":{\"context\":\"Title of the public help entry explaining the current public page.\",\"text\":\"À quoi sert cette page ?\"},\"common.public_help.privacy.description\":{\"context\":\"Description of the privacy policy entry in the public help menu.\",\"text\":\"Traitement des données et cadre provisoire\"},\"common.public_help.privacy.label\":{\"context\":\"Label of the privacy policy entry in the public help menu.\",\"text\":\"Politique de confidentialité\"}}','completed',1,NULL,'2026-08-01 09:08:55','2026-08-01 09:09:03','2026-08-01 09:08:56','2026-08-01 09:09:03'),
(25,'omo_decision_group_majority_judgment','en','094e9ddc94cdf8561572dec90453b2ff8e5961a0c3f04a225aa44c5ce99bead0','{\"decisions.majority_judgment.action.apply\":{\"context\":\"Button label to apply the settings modal changes.\",\"text\":\"Appliquer\"},\"decisions.majority_judgment.action.close\":{\"context\":\"Button label to close the settings modal.\",\"text\":\"Fermer\"},\"decisions.majority_judgment.action.configure\":{\"context\":\"Button label to open the settings modal.\",\"text\":\"Configurer\"},\"decisions.majority_judgment.action.create\":{\"context\":\"Submit label for a new majority judgment.\",\"text\":\"Créer le scrutin\"},\"decisions.majority_judgment.action.proposal_apply\":{\"context\":\"Button label used to save proposal detail popup fields.\",\"text\":\"Enregistrer les détails\"},\"decisions.majority_judgment.action.save\":{\"context\":\"Submit label for an existing majority judgment.\",\"text\":\"Enregistrer le scrutin\"},\"decisions.majority_judgment.action.saving\":{\"context\":\"Temporary label while saving.\",\"text\":\"Enregistrement…\"},\"decisions.majority_judgment.action.submit_response\":{\"context\":\"Submit label for a new response.\",\"text\":\"Enregistrer mes mentions\"},\"decisions.majority_judgment.action.submitting_response\":{\"context\":\"Temporary label while saving a response.\",\"text\":\"Enregistrement du vote…\"},\"decisions.majority_judgment.action.update_response\":{\"context\":\"Submit label when updating an existing response.\",\"text\":\"Mettre à jour mes mentions\"},\"decisions.majority_judgment.change_method\":{\"context\":\"Secondary action to go back to the method chooser.\",\"text\":\"Changer de méthode\"},\"decisions.majority_judgment.description\":{\"context\":\"Description of the majority judgment management screen.\",\"text\":\"Créez un scrutin où chaque participant attribue une mention à chaque proposition sur une échelle commune.\"},\"decisions.majority_judgment.drawer_title\":{\"context\":\"Drawer title re