ajority_judgment.field.scale_active\":{\"context\":\"Label for one majority judgment mention activation toggle.\",\"text\":\"Active\"},\"decisions.majority_judgment.field.scale_center_hint\":{\"context\":\"Hint explaining that the central mention stays excluded from the majority computation when enabled.\",\"text\":\"La mention centrale reste hors calcul si elle est active.\"},\"decisions.majority_judgment.field.scale_customize\":{\"context\":\"Toggle label used to reveal mention customization controls in majority judgment settings.\",\"text\":\"Redéfinir les mentions\"},\"decisions.majority_judgment.field.scale_default_summary\":{\"context\":\"Summary shown in the settings recap when majority judgment mention customization is disabled.\",\"text\":\"Valeurs par défaut\"},\"decisions.majority_judgment.field.scale_empty\":{\"context\":\"Fallback text when no mention is active in the configured scale.\",\"text\":\"Aucune mention active\"},\"decisions.majority_judgment.field.scale_label\":{\"context\":\"Label for one majority judgment mention label input.\",\"text\":\"Libellé\"},\"decisions.majority_judgment.field.scale_slot\":{\"context\":\"Label for one configurable slot of the majority judgment scale.\",\"text\":\"Mention {index}\"},\"decisions.majority_judgment.field.scale_slot_prefix\":{\"context\":\"Visible prefix shown before the colored dot for one configurable majority judgment mention slot.\",\"text\":\"Mention\"},\"decisions.majority_judgment.field.scale_summary\":{\"context\":\"Summary label for the configurable majority judgment scale.\",\"text\":\"Échelle configurable jusqu’à 7 mentions\"},\"decisions.majority_judgment.field.select_all\":{\"context\":\"Help text for the participation form.\",\"text\":\"Attribuez une mention à chaque proposition.\"},\"decisions.majority_judgment.field.settings\":{\"context\":\"Section title for judgment-specific settings.\",\"text\":\"Paramètres du scrutin\"},\"decisions.majority_judgment.field.status\":{\"context\":\"Label