(26,'omo_decision_proposals','en','712cca4686d7e6dfdacf9ede998972a5a5c80d130c76074d1369558da959f829','{\"decisions.proposals.add_title\":{\"context\":\"Title of the public consultation proposal form.\",\"text\":\"Ajouter une proposition\"},\"decisions.proposals.denied.consultation_not_started\":{\"context\":\"Error shown when the consultation has not started yet.\",\"text\":\"La consultation n’a pas encore commencé.\"},\"decisions.proposals.denied.default\":{\"context\":\"Fallback error for public proposal submission.\",\"text\":\"Ce lien ne permet pas d’ajouter des propositions pour le moment.\"},\"decisions.proposals.denied.evaluation_started\":{\"context\":\"Error shown when evaluation has already started.\",\"text\":\"La phase de vote a déjà commencé.\"},\"decisions.proposals.denied.invalid_decision\":{\"context\":\"Error shown when the decision cannot be loaded.\",\"text\":\"Le scrutin n’a pas pu être chargé.\"},\"decisions.proposals.denied.option_disabled\":{\"context\":\"Error shown when public proposal submission is disabled for the decision.\",\"text\":\"L’ajout de propositions n’est pas activé pour ce scrutin.\"},\"decisions.proposals.denied.participant_inactive\":{\"context\":\"Error shown when the participant is inactive.\",\"text\":\"Ce participant n’est plus actif pour ce scrutin.\"},\"decisions.proposals.denied.participant_not_found\":{\"context\":\"Error shown when no authorized participant can be found.\",\"text\":\"Aucun participant autorisé n’a été retrouvé pour ce lien ou ce compte.\"},\"decisions.proposals.denied.participant_status_declined\":{\"context\":\"Error shown when the participant declined the decision.\",\"text\":\"Votre participation a été refusée pour ce scrutin.\"},\"decisions.proposals.denied.participant_status_revoked\":{\"context\":\"Error shown when the participant access was revoked.\",\"text\":\"Votre accès à ce scrutin a été révoqué.\"},\"decisions.proposals.description_label\":{\"context\":\"Description field label in the public consultation proposal form.\",\"text\":\"Description\"},\"decisions.proposals.description_placeholder\":{\"context\":\"Description field placeholder in the public consultation proposal form.\",\"text\":\"Contexte, détails, arguments utiles…\"},\"decisions.proposals.feedback_denied\":{\"context\":\"Feedback shown when the public proposal link is no longer available.\",\"text\":\"Ce lien ne permet pas d’ajouter des propositions pour le moment.\"},\"decisions.proposals.feedback_duplicate\":{\"context\":\"Feedback shown when submitted public proposals are all duplicates.\",\"text\":\"Toutes les propositions soumises existent déjà.\"},\"decisions.proposals.feedback_empty\":{\"context\":\"Feedback shown when no public proposal was submitted.\",\"text\":\"Ajoutez au moins une proposition.\"},\"decisions.proposals.feedback_error\":{\"context\":\"Feedback shown when a public proposal cannot be saved.\",\"text\":\"Impossible d’ajouter la proposition pour le moment.\"},\"decisions.proposals.feedback_success_one\":{\"context\":\"Success message after adding one public consultation proposal.\",\"text\":\"Proposition ajoutée à la consultation.\"},\"decisions.proposals.feedback_success_other\":{\"context\":\"Success message after adding several public consultation proposals.\",\"text\":\"{count} propositions ajoutées à la consultation.\"},\"decisions.proposals.info_url_label\":{\"context\":\"Information URL field label in the public consultation proposal form.\",\"text\":\"URL d’information\"},\"decisions.proposals.open_intro\":{\"context\":\"Introduction shown above the public consultation proposal form.\",\"text\":\"La consultation est ouverte. Vous pouvez proposer une nouvelle option avec son contexte et un lien d’information.\"},\"decisions.proposals.order_hint\":{\"context\":\"Helper text explaining how a public consultation proposal is initially ordered.\",\"text\":\"La proposition sera ajoutée à la fin de la liste. Son ordre détaillé reste gérable ensuite dans l’interface principale.\"},\"decisions.proposals.submit\":{\"context\":\"Submit button in the public consultation proposal form.\",\"text\":\"Ajouter la proposition\"},\"decisions.proposals.title_label\":{\"context\":\"Title field label in the public consultation proposal form.\",\"text\":\"Titre\"},\"decisions.proposals.title_placeholder\":{\"context\":\"Title field placeholder in the public consultation proposal form.\",\"text\":\"Nom de la proposition\"}}','completed',1,NULL,'2026-08-01 09:08:56','2026-08-01 09:09:03','2026-08-01 09:08:56','2026-08-01 09:09:03'),
(27,'omo_topbar','en','63bc941593ac5e3955c168a0997f53faa3c967e686af49fe333b24f34908d4d9','{\"topbar.bug.button\":{\"context\":\"Topbar bug report button label in OMO pages.\",\"text\":\"Bug\"},\"topbar.bug.title\":{\"context\":\"Topbar bug report modal title in OMO pages.\",\"text\":\"Signaler un bug\"},\"topbar.bug.unavailable_html\":{\"context\":\"Fallback HTML shown when the bug report form cannot be loaded from the OMO topbar.\",\"text\":\"<p>Formulaire indisponible.</p>\"},\"topbar.close\":{\"context\":\"Generic close button label for the OMO topbar modal and drawer.\",\"text\":\"Fermer\"},\"topbar.drawer.default_title\":{\"context\":\"Fallback drawer title for the OMO topbar when no specific title is provided.\",\"text\":\"Panneau lateral\"},\"topbar.help.button\":{\"context\":\"Topbar help menu button label in OMO pages.\",\"text\":\"Aide\"},\"topbar.help.fallback_label\":{\"context\":\"Fallback label for a help item when no label is available in the OMO topbar.\",\"text\":\"Aide\"},\"topbar.help.faq.description\":{\"context\":\"Description of the FAQ help entry in the OMO topbar.\",\"text\":\"Acces aux questions les plus courantes, avec moteur de recherche pour trouver facilement la reponse a ses questions.\"},\"topbar.help.faq.label\":{\"context\":\"Label of the FAQ help entry in the OMO topbar.\",\"text\":\"FAQ\"},\"topbar.help.faq.title\":{\"context\":\"Title of the FAQ help entry in the OMO topbar.\",\"text\":\"FAQ OMO\"},\"topbar.help.pending_html\":{\"context\":\"Fallback HTML shown when a help item exists but does not yet have content in the OMO topbar.\",\"text\":\"<p>Contenu a venir.</p>\"},\"topbar.help.privacy.label\":{\"context\":\"Label of the privacy policy text link shown in the OMO topbar help menu.\",\"text\":\"Politique de confidentialite\"},\"topbar.help.terms.label\":{\"context\":\"Label of the terms and conditions text link shown in the OMO topbar help menu.\",\"text\":\"Conditions generales\"},\"topbar.help.tour.description\":{\"context